/** Preuves d'une opération pour un type de projet (entrée propre au type, sinon commune). */
export const preuvesDe = (type: TypeProjet, rang: string): PreuvesOperationCR | undefined =>
  PREUVES_CR.find((p) => p.rang === rang && (p.types === null || p.types.includes(type)))
